import { test, expect } from '@playwright/test';

test.describe('Short-term insurance policy lifecycle', () => {
  test('AC-1: broker creates a new client', async ({ page }) => {
    await page.getByRole('button', { name: 'New Quote' }).click();
    await page.getByTestId('client-name').fill('John Smith');
    await page.getByTestId('save-client').click();
    await expect(page.getByTestId('client-name')).toHaveValue('John Smith');
  });

  test('AC-2: broker generates a quote', async ({ page }) => {
    await page.getByTestId('product-select').selectOption('motor');
    await page.getByRole('button', { name: 'Recalculate' }).click();
    await expect(page.getByTestId('premium-amount')).not.toBeEmpty();
  });

  test('AC-3: broker binds a quote', async ({ page }) => {
    await page.getByRole('button', { name: 'Bind Policy' }).click();
    await expect(page.getByTestId('policy-status')).toHaveText('Active');
  });

  test('AC-4: broker captures mid-term amendment', async ({ page }) => {
    await page.getByTestId('sum-insured').fill('500000');
    await page.getByRole('button', { name: 'Recalculate' }).click();
    await expect(page.getByTestId('premium-amount')).not.toBeEmpty();
  });

  test('AC-6: reinsurance is saved and reflected', async ({ page }) => {
    await page.getByTestId('reinsurance-percentage').fill('25');
    await page.getByRole('button', { name: 'Recalculate' }).click();
    await expect(page.getByTestId('confirm-reinsurance')).toBeVisible();
    await expect(page.getByTestId('reinsurance-saved-value')).toHaveText('25%');
  });
});
